  {% for subject in dataset.keywords.all %}
    {{ subject.display_label }}
  {% endfor %}
  {% for tag in dataset.tags.all %}
    {{ tag }}
  {% endfor %}

{% endif %}



{% if dataset.dates.exists %}
{% for date in dataset.dates.all %}
    {{ date.value }}{% endfor %}

{% endif %}


  {{ uri }}


{% if dataset.license %}
